WITH parsed AS (SELECT id, log_ts, level, status_code, payload_json, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace FROM app_logs WHERE status_code != 377) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, level, ROUND(SUM(duration_sec) / NULLIF(COUNT(CASE WHEN level = 'WARN' THEN 1 END), 0), 2) AS duration_sec_per_warn, ROUND(AVG(status_code), 2) AS avg_status_code FROM parsed GROUP BY CUBE (DATE_TRUNC('DAY', log_ts), level) ORDER BY duration_sec_per_warn NULLS FIRST
